const apiKey = 'D=m-4.@O?KGN<hp_;5HG<6)[f#g!!%!f){xc~yY<*(=rpQf2B*{G+kxg0*S(XG2t';
const cvsBaseUrl = 'http://192.168.1.29:8080/wp-json/keoni/v1/cvs';
const jobBaseUrl = 'http://192.168.1.29:8080/wp-json/keoni/v1/job';
const chunkSize = 200;
const limit = 100;
const maxCvCount = 300;
let offset = 0;
const usable = [];

const jobPostId = $json?.body?.job_post_id;
if (!jobPostId) {
  throw new Error('Missing job_post_id in webhook payload');
}
const workflowStartedAtMs = Number($json?.body?.workflow_started_at_ms || $json?.workflow_started_at_ms || Date.now());
const workflowStartedAt = $json?.body?.workflow_started_at || $json?.workflow_started_at || new Date(workflowStartedAtMs).toISOString();

const stripHtml = (value) => {
  if (!value) return '';
  return String(value).replace(/<[^>]*>/g, ' ');
};

const hasText = (cv) => {
  const sources = [
    cv.title,
    cv.application_title,
    cv.job_title,
    cv.resume,
    cv.skills,
    cv.keywords,
    cv.text_content,
    cv.description,
  ];
  const combined = stripHtml(sources.filter(Boolean).join(' '))
    .replace(/\s+/g, ' ')
    .trim();
  return combined.length >= 10;
};

const headers = { 'X-API-Key': apiKey };
const job = await this.helpers.httpRequest({
  method: 'GET',
  url: `${jobBaseUrl}/${jobPostId}` ,
  headers,
});
job.workflow_started_at = workflowStartedAt;
job.workflow_started_at_ms = workflowStartedAtMs;
job.meta = (job && typeof job.meta === 'object' && job.meta) ? job.meta : {};
job.meta.workflow_started_at = workflowStartedAt;
job.meta.workflow_started_at_ms = workflowStartedAtMs;

while (usable.length < maxCvCount) {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `${cvsBaseUrl}?offset=${offset}&limit=${limit}` ,
    headers,
  });

  const items = Array.isArray(response.items) ? response.items : [];
  const filtered = items.filter(hasText);
  if (filtered.length) {
    usable.push(...filtered);
  }

  if (items.length < limit) {
    break;
  }

  offset += limit;
}

if (!usable.length) {
  return [{ json: { ...job, cvs: [], workflow_started_at: workflowStartedAt, workflow_started_at_ms: workflowStartedAtMs } }];
}

const selected = usable.slice(0, maxCvCount);
const chunks = [];
for (let i = 0; i < selected.length; i += chunkSize) {
  const copy = JSON.parse(JSON.stringify(job));
  copy.cvs = selected.slice(i, i + chunkSize);
  copy.workflow_started_at = workflowStartedAt;
  copy.workflow_started_at_ms = workflowStartedAtMs;
  chunks.push({ json: copy });
}

return chunks;

function normalizeList(value) {
  if (Array.isArray(value)) {
    return value.map(v => String(v).trim()).filter(Boolean);
  }
  if (!value) {
    return [];
  }
  return String(value)
    .replace(/<[^>]*>/g, ' ')
    .split(/[,;\n]+/)
    .map(v => v.trim())
    .filter(Boolean);
}

function ensureMetadata(value) {
  if (!value) {
    return {};
  }
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        return parsed;
      }
      return {};
    } catch (error) {
      return {};
    }
  }
  if (typeof value === 'object' && !Array.isArray(value)) {
    return value;
  }
  return {};
}

function stripHtml(value) {
  if (!value) {
    return '';
  }
  return String(value).replace(/<[^>]*>/g, ' ');
}

function collectText(cv, meta) {
  const sources = [
    cv.title,
    cv.application_title,
    cv.job_title,
    cv.text_content,
    cv.resume,
    cv.skills,
    cv.keywords,
    cv.description,
    meta.summary,
    meta.experience,
    meta.notes,
  ].filter(Boolean);

  if (!sources.length) {
    return '';
  }

  return sources
    .map(stripHtml)
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const jobRaw = $json;
const cvs = Array.isArray(jobRaw.cvs) ? jobRaw.cvs : [];
const normalizedCvs = cvs
  .map(cv => {
    const metadata = ensureMetadata(cv.metadata);
    const combined = collectText(cv, metadata);
    return {
      ...cv,
      metadata,
      text_content: combined,
    };
  })
  .filter(cv => (cv.text_content || '').length >= 10);

if (!normalizedCvs.length) {
  return [];
}

const job = {
  id: jobRaw.id,
  title: jobRaw.title,
  description: jobRaw.content || jobRaw.description || '',
  excerpt: jobRaw.excerpt || '',
  keywords: normalizeList(jobRaw.keywords),
  location: jobRaw.location || '',
  workflow_started_at: jobRaw.workflow_started_at || jobRaw.meta?.workflow_started_at || null,
  workflow_started_at_ms: Number(jobRaw.workflow_started_at_ms || jobRaw.meta?.workflow_started_at_ms || 0) || null,
  meta: jobRaw.meta || {},
};

const items = normalizedCvs.map(cv => ({ json: { job, cv } }));
return items;

const items = $input.all();
if (!items.length) {
  return [];
}
const job = items[0].json.job;
const cvs = items.map(item => item.json.cv);
return [{ json: { job, cvs } }];
